import json
import itertools

# Input variables
start_location = "Fisherman's Wharf"
start_time_minutes = 9 * 60  # 9:00

# Travel times (minutes) between locations
travel_minutes = {
    "Fisherman's Wharf": {
        "Golden Gate Park": 25,
        "Presidio": 17,
        "Richmond District": 18
    },
    "Golden Gate Park": {
        "Fisherman's Wharf": 24,
        "Presidio": 11,
        "Richmond District": 7
    },
    "Presidio": {
        "Fisherman's Wharf": 19,
        "Golden Gate Park": 12,
        "Richmond District": 7
    },
    "Richmond District": {
        "Fisherman's Wharf": 18,
        "Golden Gate Park": 9,
        "Presidio": 7
    }
}

# Participants with constraints
people = [
    {
        "name": "Melissa",
        "location": "Golden Gate Park",
        "start": 8 * 60 + 30,   # 8:30
        "end": 20 * 60,         # 20:00
        "min_duration": 15
    },
    {
        "name": "Nancy",
        "location": "Presidio",
        "start": 19 * 60 + 45,  # 19:45
        "end": 22 * 60,         # 22:00
        "min_duration": 105
    },
    {
        "name": "Emily",
        "location": "Richmond District",
        "start": 16 * 60 + 45,  # 16:45
        "end": 22 * 60,         # 22:00
        "min_duration": 120
    }
]

def get_travel(a, b):
    if a == b:
        return 0
    return travel_minutes[a][b]

def fmt_time(m):
    h = m // 60
    mn = m % 60
    return f"{h}:{mn:02d}"

def compute_latest_arrivals(order):
    n = len(order)
    L = [None] * n
    # Last person
    last = order[-1]
    if last["start"] + last["min_duration"] > last["end"]:
        return None
    L[-1] = last["end"] - last["min_duration"]
    # Backward for others
    for i in range(n - 2, -1, -1):
        cur = order[i]
        nxt = order[i + 1]
        T = get_travel(cur["location"], nxt["location"])
        emax = min(cur["end"], L[i + 1] - T)
        if cur["start"] + cur["min_duration"] > emax:
            return None
        L[i] = emax - cur["min_duration"]
    return L

def build_schedule(order, L):
    itinerary = []
    current_loc = start_location
    current_time = start_time_minutes
    total_wait = 0
    total_travel = 0

    n = len(order)
    for i, person in enumerate(order):
        travel_t = get_travel(current_loc, person["location"])
        total_travel += travel_t
        arrival = current_time + travel_t
        start_meet = max(arrival, person["start"])
        # Determine emax at this step
        if i == n - 1:
            emax = person["end"]
        else:
            T_next = get_travel(person["location"], order[i + 1]["location"])
            emax = min(person["end"], L[i + 1] - T_next)
        # Meeting end: maximize within feasibility to reduce waiting later
        end_meet = max(start_meet + person["min_duration"], emax)
        # Wait time at this step
        if arrival < start_meet:
            total_wait += (start_meet - arrival)
        # Append itinerary
        itinerary.append({
            "action": "meet",
            "location": person["location"],
            "person": person["name"],
            "start_time": fmt_time(start_meet),
            "end_time": fmt_time(end_meet)
        })
        current_time = end_meet
        current_loc = person["location"]

    return {
        "itinerary": itinerary,
        "metrics": {
            "people_met": n,
            "total_wait": total_wait,
            "total_travel": total_travel,
            "end_time": current_time
        }
    }

def feasible_schedule_for_order(order):
    # Compute latest arrivals (backward feasibility)
    L = compute_latest_arrivals(order)
    if L is None:
        return None
    # Check arrival feasibility for the first person from starting point
    first = order[0]
    first_arrival = start_time_minutes + get_travel(start_location, first["location"])
    if first_arrival > L[0]:
        return None
    # Build concrete schedule with forward pass
    schedule = build_schedule(order, L)
    return schedule

def pick_best_schedule():
    best = None

    # Iterate over subsets in decreasing size to maximize number of people met
    for k in range(len(people), 0, -1):
        found_any = False
        for combo in itertools.combinations(people, k):
            for order in itertools.permutations(combo):
                sched = feasible_schedule_for_order(order)
                if sched is None:
                    continue
                found_any = True
                if best is None:
                    best = sched
                else:
                    # Compare based on goals:
                    # 1) Maximize people_met (already fixed by k)
                    # 2) Minimize total_wait
                    # 3) Minimize total_travel
                    # 4) Earliest end_time
                    b = best["metrics"]
                    s = sched["metrics"]
                    criteria_best = ( -b["people_met"], b["total_wait"], b["total_travel"], b["end_time"] )
                    criteria_new = ( -s["people_met"], s["total_wait"], s["total_travel"], s["end_time"] )
                    if criteria_new < criteria_best:
                        best = sched
        if found_any:
            break  # We found at least one schedule meeting k people; no need to check smaller k
    return best

def main():
    best = pick_best_schedule()
    output = {"itinerary": []}
    if best:
        output["itinerary"] = best["itinerary"]
    print(json.dumps(output, ensure_ascii=False))

if __name__ == "__main__":
    main()
